state.actual_source:
export contract Settlement { source:text label=label_Charge_source, invoice:text label="Invoice reference"@{nl="Factuurreferentie"}, revision:int, amount:money, received:datetime label=label_Settlement_received, state:enum(paid,refunded,void,unknown) label={text=label_Settlement_state,values={paid=label_Settlement_state_paid,refunded="Refunded"@{nl="Terugbetaald"},void=label_Settlement_state_void,unknown=label_Settlement_state_unknown}} } label="Settlement outcome"@{nl="Afwikkelingsresultaat"}
derive Invoice.received:money = sum(row.Attempt as attempt where attempt.kind==collection and attempt.status==succeeded select attempt.amount,row.currency)+sum(row.ExternalPayment as payment select payment.amount,row.currency) label="Received payments"@{nl="Ontvangen betalingen"}
derive Invoice.refunded:money = sum(row.Attempt as attempt where attempt.kind==refund and attempt.status==succeeded select attempt.amount,row.currency) label="Refunded amount"@{nl="Terugbetaald bedrag"}
scenario apply_result on=ProviderReceipt
      emit InvoiceSettlement {value={source=attempt.parent.source,invoice=attempt.parent.id,revision=attempt.parent.version,amount=attempt.amount,received=now,state=paid}}
      emit InvoiceSettlement {value={source=attempt.parent.source,invoice=attempt.parent.id,revision=attempt.parent.version,amount=attempt.amount,received=now,state=refunded}}
